package com.signalradar.app.scan

import android.content.Context

/**
 * Manufacturer lookups:
 *  - MAC OUI (first 3 bytes of a Wi-Fi BSSID or a public Bluetooth address) -> company (IEEE registry, ~40k entries)
 *  - Bluetooth SIG company identifier (in BLE manufacturer data) -> company (~4k entries)
 *  - 16-bit service UUID -> service name
 * Tables are generated by scripts/gen_vendor_data.py into assets/.
 */
object Vendors {
    @Volatile private var oui: Map<Int, String> = mapOf(0xB41E52 to "Flock Safety")
    @Volatile private var companies: Map<Int, String> = mapOf(
        0x004C to "Apple, Inc.", 0x0006 to "Microsoft", 0x0075 to "Samsung Electronics Co. Ltd.",
        0x00E0 to "Google", 0x01AB to "Meta Platforms, Inc.", 0x058E to "Meta Platforms Technologies, LLC",
        0x0D53 to "Luxottica Group S.p.A", 0x03C2 to "Snapchat Inc", 0x09C8 to "XUNTONG",
    )
    @Volatile private var uuids: Map<Int, String> = emptyMap()
    @Volatile var loaded = false
        private set

    val ouiCount get() = oui.size
    val companyCount get() = companies.size

    fun load(ctx: Context) {
        if (loaded) return
        oui = readTable(ctx, "oui.txt", oui)
        companies = readTable(ctx, "companies.txt", companies)
        uuids = readTable(ctx, "uuids.txt", uuids)
        loaded = true
    }

    private fun readTable(ctx: Context, name: String, fallback: Map<Int, String>): Map<Int, String> {
        val m = HashMap<Int, String>(fallback)
        try {
            ctx.assets.open(name).bufferedReader().useLines { lines ->
                lines.forEach { line ->
                    val tab = line.indexOf('\t')
                    if (tab > 0) {
                        val k = line.substring(0, tab).toIntOrNull(16)
                        if (k != null) m[k] = line.substring(tab + 1)
                    }
                }
            }
        } catch (_: Exception) {
        }
        return m
    }

    fun macBytes(mac: String): IntArray? {
        val parts = mac.split(':', '-')
        if (parts.size < 6) return null
        val out = IntArray(6)
        for (i in 0 until 6) out[i] = parts[i].toIntOrNull(16) ?: return null
        return out
    }

    fun ouiVendor(mac: String): String? {
        val b = macBytes(mac) ?: return null
        return oui[(b[0] shl 16) or (b[1] shl 8) or b[2]]
    }

    /** Locally administered bit: randomized / virtual MACs never belong to a registered OUI. */
    fun isLocallyAdministered(mac: String): Boolean {
        val b = macBytes(mac) ?: return false
        return (b[0] and 0x02) != 0
    }

    fun prefix(mac: String): String = mac.take(8).uppercase()

    fun company(id: Int): String? = companies[id]
    fun uuid16(id: Int): String? = uuids[id]
}
